def canonical_provider_surfaces(g,mesh):
    """Restore direct owner order before welding independently cached meshes.

    Each still-unwelded provider has one face kind/owner, so these dedicated
    FACE fields also identify its vertices and edges without mixed ownership.
    Stable minor/major sorts retain every provider's internal element order.
    Do not sort on st_cn_owner: packed diagnostic points can promote that
    attribute to POINT and give it a different meaning.

    Canonicalizing before the weld also stabilizes original-vertex references
    and the separator's local frame. No position or topology is regenerated.
    """
    for domain in ('POINT','EDGE','FACE'):
        for key in ('owner','kind'):
            order=g.node('GeometryNodeSortElements','Canonical provider '+domain.lower()+' '+key)
            order.domain=domain
            g.bind(mesh,order.inputs['Geometry'])
            g.bind(c.named(g,'_cn_face_'+key,'INT'),order.inputs['Sort Weight'])
            mesh=order.outputs['Geometry']
    return mesh


