    ci.pair_with_output(co);g.bind(c.choose(g,within,n,0,'INT'),ci.inputs['Iterations']);at=c.V(g,ci.outputs['Iteration'])
    geo,status,diagnostics=corridor_owner(g,inp,mouths,valid,at,dimensions=dimensions,local_frames=local_frames,port_paths=port_paths,interpolation=interpolation)
    for key,value in (('Surfaces',geo),('Status',status),('Diagnostics',diagnostics)):
        g.bind(boundary._join(g,ci.outputs[key],value),co.inputs[key])
    valid=valid*within*c.choose(g,g.math('GREATER_THAN',n,.5),c._stat(g,co.outputs['Status'],c.named(g,'valid','BOOLEAN')),1.)
    surfaces=co.outputs['Surfaces'];statuses=co.outputs['Status'];diagnostics=co.outputs['Diagnostics']
    if external:
        extra,extra_valid=_external_surfaces(g,inp,mouths,boundary_valid,local_frames=local_frames,port_paths=port_paths,interpolation=interpolation,
            dimensions=dimensions and aggregate_patch is not None,selection_cuts=aggregate_patch is not None)
        valid=valid*extra_valid;n=n+c._count(g,inp.outputs['External Approaches'])
        surfaces=boundary._join(g,surfaces,extra.outputs['Surfaces'])
        statuses=boundary._join(g,statuses,extra.outputs['Status'])
